import type { Meta, StoryObj } from "@storybook/vue3";
import { h } from "vue";
import { KozmosHeading } from "../../index";

/**
 * Vue's Heading: the stories React's has, with the same names and args,
 * each inside the KozmosThemeProvider the Storybook's decorator gives every
 * story. test/parity draws each of React's in both and holds Vue's render to
 * React's. Generated by `port Heading`; AllLevels drawn by hand.
 */
type Args = Record<string, unknown>;
const SLOTS = ["children"];

const meta: Meta<Args> = {
  title: "Vue/Foundations/Typography/Heading",
  component: KozmosHeading,
  // React's node props are Vue's slots: `children` the default slot, the
  // rest slots of their own names, each drawing its arg's text.
  render: (args) => ({
    setup: () => () => {
      const props: Args = {};
      const slots: Record<string, () => string> = {};
      for (const [key, value] of Object.entries(args)) {
        if (!SLOTS.includes(key)) props[key] = value;
        else if (value !== undefined && value !== null)
          slots[key === "children" ? "default" : key] = () => String(value);
      }
      return h(KozmosHeading, props, slots);
    },
  }),
};

export default meta;
type Story = StoryObj<Args>;

export const Default: Story = {
  args: {
    children: "Heading 1",
    level: 1,
  },
};

/** React's AllLevels: every level, H1 to H6, each at its own size. */
export const AllLevels: Story = {
  render: () => ({
    components: { KozmosHeading },
    template: `
      <div class="space-y-4">
        <KozmosHeading :level="1">Heading 1</KozmosHeading>
        <KozmosHeading :level="2">Heading 2</KozmosHeading>
        <KozmosHeading :level="3">Heading 3</KozmosHeading>
        <KozmosHeading :level="4">Heading 4</KozmosHeading>
        <KozmosHeading :level="5">Heading 5</KozmosHeading>
        <KozmosHeading :level="6">Heading 6</KozmosHeading>
      </div>
    `,
  }),
};
